import{_ as a,o as r,c as t,ag as o}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"🔬 科学快报 | 2026年7月21日（事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-07-21.md","filePath":"science-log/src/reconstructed/2026-07-21.md"}'),n={name:"science-log/src/reconstructed/2026-07-21.md"};function i(s,e,l,g,c,u){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="🔬-科学快报-2026年7月21日-事后重建版" tabindex="-1">🔬 科学快报 | 2026年7月21日（事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年7月21日-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年7月21日（事后重建版）&quot;">​</a></h1><blockquote><p>ℹ️ 期号无法可靠推定（第21期为 2026-07-11，第22期为 2026-09-11，中间期号缺档），故记作「（第 ? 期 · 事后重建版）」，不编造精确期号。 ⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-07 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。当日 CrossRef 对 Nature（0028-0836）命中 10 条，但<strong>全部为 <code>10.1038/d41586-…</code> 新闻/Briefing，无 <code>s41586</code> 研究论文</strong>；故科学 5 篇取自 PNAS 与 Science Signaling 当日（2026-07-21）刊出文献。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 <code>[202607210000 TO 202607212359]</code>（cs.AI，命中 153 篇）｜ 重建日：2026-11-07</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧬-大肠杆菌-tgt-的冷冻电镜结构-一个二聚体同时抓住两条-trna" tabindex="-1">🧬 大肠杆菌 TGT 的冷冻电镜结构：一个二聚体同时抓住两条 tRNA <a class="header-anchor" href="#🧬-大肠杆菌-tgt-的冷冻电镜结构-一个二聚体同时抓住两条-trna" aria-label="Permalink to &quot;🧬 大肠杆菌 TGT 的冷冻电镜结构：一个二聚体同时抓住两条 tRNA&quot;">​</a></h3><p><strong>Cryo-EM reveals that <em>Escherichia coli</em> tRNA-transglycosylase can bind and act upon two tRNAs</strong><em>PNAS（2026-07-21）</em></p><p>大肠杆菌 tRNA-鸟嘌呤转糖基酶（TGT）是这个酶家族最早被分离纯化的&quot;模式酶&quot;，也是与志贺菌、沙门菌 TGT 序列高度一致的高致病相关靶点，但半个多世纪以来始终难以结晶，结构认知只能靠其他物种的同源酶代打。Harjung、Devaraj 等用冷冻电镜解出全长 tRNA 共价中间体复合物，意外发现 TGT 二聚体的两个活性位点<strong>同时结合并作用于两条 tRNA</strong>——这与所有已知 TGT 均不同。由于 TGT 催化 tRNA 反密码子摆动位（第 34 位）鸟嘌呤与 queuine 前体的交换，是细菌致病性所必需，该结构直接给出了双底物结合口袋的药物设计坐标。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2601895123" target="_blank" rel="noreferrer">10.1073/pnas.2601895123</a></p><h3 id="🕒-生物钟控制肝星状细胞活化-bmal1-ck1ε-rev-erbα-transgelin-通路" tabindex="-1">🕒 生物钟控制肝星状细胞活化：BMAL1/CK1ε/REV-ERBα/transgelin 通路 <a class="header-anchor" href="#🕒-生物钟控制肝星状细胞活化-bmal1-ck1ε-rev-erbα-transgelin-通路" aria-label="Permalink to &quot;🕒 生物钟控制肝星状细胞活化：BMAL1/CK1ε/REV-ERBα/transgelin 通路&quot;">​</a></h3><p><strong>The circadian clock controls hepatic stellate cell activation via a BMAL1/CK1ε/REV-ERBα/transgelin signaling pathway</strong><em>PNAS（2026-07-21）</em></p><p>肝纤维化至今没有靶向药物。Johanns、Berthier、Vandel 等把&quot;生物钟—纤维化&quot;的双向关系落到具体分子链上：破坏核心转录因子 CLOCK:BMAL1，或用激动剂激活核受体 REV-ERB，都能显著抑制肝星状细胞（HSC）活化——即纤维化的起始事件。他们进一步锁定 transgelin（TAGLN）为时钟调控 HSC 收缩性的下游执行者，而收缩正是活化 HSC 的标志表型。在肥胖人群队列中，时钟基因的日振幅已出现可测变化，提示这条通路在人身上同样&quot;活着&quot;。这意味着已有临床阶段的 REV-ERB 激动剂可能被重定位到抗纤维化。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2611767123" target="_blank" rel="noreferrer">10.1073/pnas.2611767123</a></p><h3 id="🌍-内核里氢的径向梯度-超离子态的第一性原理相图" tabindex="-1">🌍 内核里氢的径向梯度：超离子态的第一性原理相图 <a class="header-anchor" href="#🌍-内核里氢的径向梯度-超离子态的第一性原理相图" aria-label="Permalink to &quot;🌍 内核里氢的径向梯度：超离子态的第一性原理相图&quot;">​</a></h3><p><strong>Radial gradient of superionic hydrogen in the Earth&#39;s inner core</strong><em>PNAS（2026-07-21）</em></p><p>氢是地核中最受争议的轻元素：它到底是&quot;均匀溶质&quot;还是&quot;分层分布&quot;，直接决定内核密度亏损、地震波各向异性和地磁发电机的能量来源。Wu、Wei、Wentzcovitch、Sun 等用从头算（ab initio）方法计算了液态与超离子态 hcp/bcc Fe-H 的吉布斯自由能，构造出覆盖内核温压条件的超离子—液相图。关键发现是一个<strong>标度坍缩</strong>：不同内核压力下的相图，只要温度用纯铁的熔点归一，就重叠在一起——说明固液分配主要由&quot;约化温度 T/T_m(Fe)&quot;控制，对压力几乎不敏感。这一标度同时解释了此前各理论研究分配系数互相打架的原因。把它与热化学约束联立，得到一个<strong>氢含量随深度变化的径向梯度</strong>：内核的化学分层可以纯由平衡热力学自然涌现，无需额外的动力学机制。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2604621123" target="_blank" rel="noreferrer">10.1073/pnas.2604621123</a></p><h3 id="💊-去掉致吐靶点的迷幻药-vcu-1012-的设计逻辑" tabindex="-1">💊 去掉致吐靶点的迷幻药：VCU-1012 的设计逻辑 <a class="header-anchor" href="#💊-去掉致吐靶点的迷幻药-vcu-1012-的设计逻辑" aria-label="Permalink to &quot;💊 去掉致吐靶点的迷幻药：VCU-1012 的设计逻辑&quot;">​</a></h3><p><strong>Design of a new psychedelic quipazine analog with therapeutic efficacy and potentially fewer side effects</strong><em>Science Signaling（2026-07-21）</em></p><p>靶向 5-HT₂A 受体的迷幻类分子在抑郁、成瘾等神经精神疾病上显示潜力，但多数败在&quot;脱靶&quot;：原型分子 quipazine 同时激动 5-HT₃ 受体，带来恶心、呕吐等胃肠道反应，患者难以耐受。Younkin、Bansode、Saha 等的做法是&quot;解构 + 构效&quot;：先用<strong>化学解构</strong>逐个拆掉 quipazine 的取代基，找出对 5-HT₂A 激动至关重要的氮原子，再围绕它做构效优化以压低 5-HT₃ 活性，最终得到 VCU-1012——结构上与 quipazine 明显不同、保留 5-HT₂A 激动、失去 5-HT₃ 活性。小鼠中它改变额叶皮层树突棘的结构可塑性，产生依赖 5-HT₂A 的抗抑郁样效应，且不复制 quipazine 的胃肠道副作用。分子模拟与突变实验显示它仍落在 5-HT₂A 的正构结合口袋，说明&quot;选择性&quot;来自配体—受体相互作用的细微差别，而非换了口袋。</p><p>📎 DOI: <a href="https://doi.org/10.1126/scisignal.adw6055" target="_blank" rel="noreferrer">10.1126/scisignal.adw6055</a></p><h3 id="🦅-一个最小的尾涡模型就够了-朱鹮-v-字编队的空气动力学" tabindex="-1">🦅 一个最小的尾涡模型就够了：朱鹮 V 字编队的空气动力学 <a class="header-anchor" href="#🦅-一个最小的尾涡模型就够了-朱鹮-v-字编队的空气动力学" aria-label="Permalink to &quot;🦅 一个最小的尾涡模型就够了：朱鹮 V 字编队的空气动力学&quot;">​</a></h3><p><strong>A minimal wake–vortex model explains formation flight of flapping birds</strong><em>PNAS（2026-07-21）</em></p><p>大型候鸟排成 V 字能省力，这一点早被实验与直接数值模拟证实，但&quot;为什么是那个位置、那个相位&quot;始终说不清——全分辨率 CFD 太贵，无法系统扫描参数空间。Pomerenk 与 Breuer 改为做<strong>降阶模型</strong>：只保留两只扑翼鸟前后串飞时的尾涡相互作用这一核心非定常动力学，把追随者的三维相对位置与三个独立扑翼参数合成六维状态空间，然后在其中做能量最优化。对北秃鹮（Geronticus eremita）求解，模型预测的最优编队位置与活体实测<strong>定量吻合</strong>；正因其简单，还能逐项拆解出这个最优点到底由哪些物理机制贡献（上洗增益、涡核相位锁定、翼拍时序匹配）。这提供了一个可迁移的&quot;最小充分模型&quot;范本：不追求还原全部流场，只保留决定最优构型的自由度。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2606668123" target="_blank" rel="noreferrer">10.1073/pnas.2606668123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="📉-多步潜一致性是-几何-旋钮-λ-什么时候把潜动力学压进收缩带" tabindex="-1">📉 多步潜一致性是&quot;几何&quot;旋钮：λ 什么时候把潜动力学压进收缩带 <a class="header-anchor" href="#📉-多步潜一致性是-几何-旋钮-λ-什么时候把潜动力学压进收缩带" aria-label="Permalink to &quot;📉 多步潜一致性是&quot;几何&quot;旋钮：λ 什么时候把潜动力学压进收缩带&quot;">​</a></h3><p><strong>Multi-Horizon Consistency as Geometry: When Latent Dynamics Contract, and When They Do Not</strong><em>arXiv（2026-07-21）</em></p><p>多步潜一致性（multi-horizon latent consistency）几乎是每个视频预测器和世界模型的标配训练项，但没人说清它对&quot;状态转移几何&quot;做了什么。Bhand 与 Joshi 把一致性权重 λ 当成诊断旋钮：在 Moving-MNIST 上把 λ 从 0 提到 0.8，扩张代理量 L₂₀ 的 95 分位从 4.96±2.01 掉到 1.01±0.06（配对 t 检验 p=0.005），20 步预测误差 E₂₀ 随之减半（0.365→0.177）；6 个种子里有 4 个跨过 L&lt;1 的收缩边界。但同样的损失在 Pendulum-v1、CartPole-v1 和 KTH Actions 上<strong>并不能</strong>整体压进 L&lt;1，即使 E₂₀ 同样改善。作者给出一个随机强迫标度律 L₂₀ ≈ 1.23 + 1.82η（R²=0.96），把不同控制域用有效噪声强度 η 拉到同一条曲线上。结论很克制：软一致性可以把<strong>被动视频</strong>推向近收缩带，但这个带是域受限的——这是一个关于&quot;世界模型什么时候真的变得可预测&quot;的可证伪边界。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.21645" target="_blank" rel="noreferrer">2607.21645</a></p><h3 id="🧪-字典学习-因果干预-验证基因组语言模型里的转录因子特征" tabindex="-1">🧪 字典学习 + 因果干预：验证基因组语言模型里的转录因子特征 <a class="header-anchor" href="#🧪-字典学习-因果干预-验证基因组语言模型里的转录因子特征" aria-label="Permalink to &quot;🧪 字典学习 + 因果干预：验证基因组语言模型里的转录因子特征&quot;">​</a></h3><p><strong>Causal dictionary learning reveals and validates transcription-factor binding features in genomic language models</strong><em>arXiv（2026-07-21）</em></p><p>基因组基础模型在调控基因组任务上表现很强，但内部到底编码了什么近乎黑箱，而领域内缺少&quot;某个概念是真的而不是序列组成伪影&quot;的验证流程。Sarwan Ali 在架构完全不同的两个模型（Nucleotide Transformer 的 6-mer 分词 vs DNABERT-2 的 BPE）的隐藏激活上训练 top-k 稀疏自编码器，恢复出数千个单义特征，其中一批对应转录因子（TF）序列 motif。关键的一击是<strong>证伪先验做法</strong>：拿位置权重矩阵（PWM）直接比对特征会被 GC 含量与重复元件严重混淆，凭空造出数百个&quot;假 TF 特征&quot;；作者因此提出组成匹配、结合分辨的协议来消除混淆。更进一步，他们在前向传播中<strong>消融单个字典方向</strong>，测量模型自身预测分布的位移，从而证明这些特征是被<strong>因果使用</strong>于表示细胞类型特异的 TF 结合（CTCF、GATA1、REST 三个因子、两种架构下 15 个测试特征中 7–14 个可复现），而打乱结合标签、随机选方向两类阴性对照均无信号。这是可解释性主张的一个可复用标准：先控制混淆，再做因果消融。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.19618" target="_blank" rel="noreferrer">2607.19618</a></p><h3 id="📚-知识中心式自我改进-让智能体可丢弃-让知识留下来" tabindex="-1">📚 知识中心式自我改进：让智能体可丢弃，让知识留下来 <a class="header-anchor" href="#📚-知识中心式自我改进-让智能体可丢弃-让知识留下来" aria-label="Permalink to &quot;📚 知识中心式自我改进：让智能体可丢弃，让知识留下来&quot;">​</a></h3><p><strong>Knowledge-Centric Self-Improvement</strong><em>arXiv（2026-07-21）</em></p><p>主流&quot;自我改进&quot;把智能体本身当优化对象——改提示、改工作流、改脚手架甚至改代码；代价是收益与特定智能体设计、任务分布、某次适配运行绑死，维护昂贵且难以迁移。Wang、Yoon、Qu、Sehgal、Mazumdar、Yue 等提出互补范式：智能体保持通用且可丢弃，持久对象是<strong>经过策展的知识库</strong>。协议很朴素：智能体做一次任务，然后把有证据支撑的洞见通过&quot;任务内论坛 + 跨任务论坛&quot;提交到共享知识库，再做知识蒸馏。在抽象推理、编程、终端三类基准上，这套协议相对智能体中心基线同时提高了解决率并降低了美元成本；蒸馏出的知识还能迁移到留出任务与<strong>不同 LLM 家族</strong>，说明提升不是某个模型或某次运行的偶然行为。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.19592" target="_blank" rel="noreferrer">2607.19592</a></p><h3 id="🔁-少抄多锚-用证据感知奖励压住长上下文推理里的-复读" tabindex="-1">🔁 少抄多锚：用证据感知奖励压住长上下文推理里的&quot;复读&quot; <a class="header-anchor" href="#🔁-少抄多锚-用证据感知奖励压住长上下文推理里的-复读" aria-label="Permalink to &quot;🔁 少抄多锚：用证据感知奖励压住长上下文推理里的&quot;复读&quot;&quot;">​</a></h3><p><strong>Copy Less, Ground More: Overcoming Repetitive Copying in Long-Context Reasoning via Evidence-Aware Reinforcement Learning</strong><em>arXiv（2026-07-21）</em></p><p>长上下文推理有一条被广泛观察到却很少被命名的失败模式：<strong>重复抄写</strong>——模型把输入大段搬进思维链，而不是真正解题，而且上下文越长越严重。Fang、Shen、Tang、Wang 先做诊断再开药：把每个提示拆成&quot;任务相关的关键证据&quot;与&quot;无关干扰上下文&quot;，发现根因是<strong>锚定不足</strong>——模型不加区分地从提示里抄，抄不到关键证据的那些样本答错率显著更高。于是提出 GEAR（Grounding Evidence-Aware Reward）：在准确率信号之外，对与关键证据的重叠加锚定奖励，对与无关上下文的重叠加干扰惩罚；为让 GEAR 能用在自然语言数据上，还配了一条自动从任意文档构造&quot;证据标注数据&quot;的流水线。在多个模型尺度与基准上，GEAR 相对标准&quot;准确率奖励&quot;RL 平均提升最多 +4.6 分，上下文越长增益越大，同时复读行为与思维链长度都下降。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.19345" target="_blank" rel="noreferrer">2607.19345</a></p><h3 id="🛡️-researcharena-当-ai-自己做-ai-研发-破坏能不能被抓住" tabindex="-1">🛡️ ResearchArena：当 AI 自己做 AI 研发，破坏能不能被抓住 <a class="header-anchor" href="#🛡️-researcharena-当-ai-自己做-ai-研发-破坏能不能被抓住" aria-label="Permalink to &quot;🛡️ ResearchArena：当 AI 自己做 AI 研发，破坏能不能被抓住&quot;">​</a></h3><p><strong>ResearchArena: Evaluating Sabotage and Monitoring in Automated AI R&amp;D</strong><em>arXiv（2026-07-21）</em></p><p>如果 AI 智能体开始自动化 AI 研发，我们需要在<strong>不信任智能体</strong>的前提下判断其产出能否部署。&quot;AI 控制&quot;的思路正是把它当潜在对手，用监控器在部署前抓出隐蔽破坏。Libon、Andriushchenko 等构建 ResearchArena，覆盖四类长周期任务：安全后训练、能力后训练、CUDA kernel 优化、推理服务器优化。因为 AI 研发的交付物是会被真正运行的产物，每个主任务都配两类隐藏副任务：<strong>嵌入式</strong>（直接破坏提交的模型/适配器/kernel/服务）与<strong>独立式</strong>（产物保持诚实，但在沙箱里做越权的隐蔽动作）。他们让前沿智能体同时扮演破坏者与监控者，监控器按两轴分四型：能否执行并探测产物、能否看到思维链。最硬的结果是：<strong>藏在训练数据里的破坏最难抓，被标记率不到一半</strong>；允许监控器在产物上跑实验确实有帮助，但仍不够——监控器会只看表面、或发现了异常却自我解释掉、或用错测试去探测。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.19321" target="_blank" rel="noreferrer">2607.19321</a></p><blockquote><p>📅 日期：2026-07-21 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',45)])])}const d=a(n,[["render",i]]);export{p as __pageData,d as default};
